function isBlocked(x,y,r=8){const minX=Math.floor((x-r)/TS),maxX=Math.floor((x+r)/TS),minY=Math.floor((y-r)/TS),maxY=Math.floor((y+r)/TS);for(let yy=minY;yy<=maxY;yy++)for(let xx=minX;xx<=maxX;xx++)if(!tiles[yy]||tiles[yy][xx]!==0){let cx=Math.max(xx*TS,Math.min(x,(xx+1)*TS)),cy=Math.max(yy*TS,Math.min(y,(yy+1)*TS));if(Math.hypot(x-cx,y-cy)<r+1)return true}return false}
function moveBody(o,dx,dy,r){if(!isBlocked(o.x+dx,o.y,r))o.x+=dx;if(!isBlocked(o.x,o.y+dy,r))o.y+=dy}
function startGame(){generate();mode='playing';ui.overlay.classList.add('hidden');ui.hud.style.display='block';ui.pause.style.display='none';ui.goal.textContent='Find the three echoes';showToast('THE PATH HAS CHANGED');last=performance.now();}
function endGame(win){mode='end';won=win;ui.hud.style.display='none';ui.pause.style.display='none';ui.overlay.classList.remove('hidden');ui.card.classList.add('end');ui.overline.textContent=win?'SIGNAL RESTORED':'FIELD NOTE / LOST';ui.title.innerHTML=win?'YOU FOUND<br>THE WAY OUT':'THE WOODS<br>KEEP YOU';ui.subtitle.textContent=win?'SOMEONE ANSWERED':'THE DARK LEARNED YOUR NAME';ui.description.textContent=win?'The gate opens into a sky you almost remember. Somewhere behind you, something exhales.':'Your lantern sputters out. The forest folds itself shut like a mouth. It will be different when you return.';ui.start.textContent='WALK AGAIN  ↗';document.querySelector('.rule').style.display='none';document.querySelector('.instructions').style.display='none';document.querySelector('.small-note').textContent=win?'NIGHT '+night+' · '+formatTime(elapsed):'THE FOREST REMEMBERS';}
function resetMenu(){mode='menu';ui.card.classList.remove('end');ui.overline.textContent='A PROCEDURAL NIGHTMARE';ui.title.innerHTML='HOLLOW<br>SIGNAL';ui.subtitle.textContent='NO TWO NIGHTS ARE THE SAME';ui.description.textContent='The forest has rearranged itself around you. Find the three lost echoes, keep your lantern alive, and reach the old gate before the thing in the trees finds you.';ui.start.textContent='ENTER THE WOODS  ↗';document.querySelector('.rule').style.display='block';document.querySelector('.instructions').style.display='grid';document.querySelector('.small-note').textContent='HEADPHONES RECOMMENDED';ui.overlay.classList.remove('hidden');ui.hud.style.display='none';}
function formatTime(s){let m=Math.floor(s/60),ss=Math.floor(s%60);return String(m).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
let toastId;function showToast(t){ui.toast.textContent=t;ui.toast.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function togglePause(){if(mode==='playing'){mode='paused';ui.pause.style.display='flex'}else if(mode==='paused'){mode='playing';ui.pause.style.display='none';last=performance.now()}}
function setKey(e,on){const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright','shift',' ','f','escape'].includes(k))e.preventDefault();if(k==='escape'&&on){togglePause();return}if(k==='f'&&on&&mode==='playing'){lantern=!lantern;showToast(lantern?'LANTERN LIT':'LANTERN COVERED');return}if(k===' '&&on&&mode==='playing'){player.stamina=Math.min(100,player.stamina+14);player.battery=Math.max(0,player.battery-4);pulse=1;showToast('STEADY YOUR BREATH');return}keys[k]=on}
addEventListener('keydown',e=>setKey(e,true));addEventListener('keyup',e=>setKey(e,false));
ui.start.addEventListener('click',()=>{if(mode==='end')resetMenu();startGame()});
for(const el of document.querySelectorAll('.touchkey')){el.addEventListener('pointerdown',e=>{e.preventDefault();el.classList.add('on');if(el.dataset.key)keys[el.dataset.key]=true;if(el.dataset.action==='run')touchRun=true;if(el.dataset.action==='lamp'&&mode==='playing'){lantern=!lantern;showToast(lantern?'LANTERN LIT':'LANTERN COVERED')}if(el.dataset.action==='pause')togglePause()});for(const ev of ['pointerup','pointercancel','pointerleave'])el.addEventListener(ev,()=>{el.classList.remove('on');if(el.dataset.key)keys[el.dataset.key]=false;if(el.dataset.action==='run')touchRun=false})}
function setupSound(){if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();let osc=audioCtx.createOscillator(),gain=audioCtx.createGain(),filter=audioCtx.createBiquadFilter();osc.type='sine';osc.frequency.value=47;filter.type='lowpass';filter.frequency.value=130;gain.gain.value=.0001;osc.connect(filter).connect(gain).connect(audioCtx.destination);osc.start();ambience={gain,osc};}audioCtx.resume();hasAudio=!hasAudio;ambience.gain.gain.setTargetAtTime(hasAudio?.025:.0001,audioCtx.currentTime,.5);ui.sound.textContent='SOUND: '+(hasAudio?'ON':'OFF')}
ui.sound.addEventListener('click',setupSound);
function tileColor(x,y){let v=Math.sin(x*12.9898+y*78.233)*43758.5453;v=v-Math.floor(v);return v}
function drawTree(x,y,s,eye=false){const sway=Math.sin(elapsed*1.1+x*.04)*1.1;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#070c09';ctx.beginPath();ctx.ellipse(2,12,15,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252f27';ctx.beginPath();ctx.ellipse(0,3,11,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#354135';ctx.beginPath();ctx.ellipse(-3,-4+sway,10,14,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#465244';ctx.beginPath();ctx.ellipse(2,-9+sway,7,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#18221b';ctx.fillRect(-2,6,4,8);if(eye&&Math.sin(elapsed*2+x)>.55){ctx.fillStyle='#a5bd78';ctx.shadowColor='#b9da7a';ctx.shadowBlur=10;ctx.fillRect(-4,-7,2,2);ctx.fillRect(2,-7,2,2)}ctx.restore()}
function drawWorld(){const camX=player.x-W/2,camY=player.y-H/2;ctx.save();ctx.translate(-camX,-camY);ctx.fillStyle='#121914';ctx.fillRect(0,0,MW*TS,MH*TS);
let x0=Math.max(0,Math.floor(camX/TS)-1),x1=Math.min(MW,Math.ceil((camX+W)/TS)+1),y0=Math.max(0,Math.floor(camY/TS)-1),y1=Math.min(MH,Math.ceil((camY+H)/TS)+1);
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){let px=x*TS,py=y*TS;if(tiles[y][x]===0){let n=tileColor(x,y);ctx.fillStyle=n>.5?'#222b23':'#1d261f';ctx.fillRect(px,py,TS,TS);ctx.fillStyle='#32372a';if(n>.74){ctx.fillRect(px+8,py+13,2,2);ctx.fillRect(px+28,py+29,1,1)}else if(n<.22){ctx.fillRect(px+19,py+7,2,1);ctx.fillRect(px+6,py+31,1,2)}}else{ctx.fillStyle='#0b110d';ctx.fillRect(px,py,TS,TS);let n=tileColor(x*5,y*3);ctx.fillStyle=n>.4?'#121b14':'#101811';ctx.beginPath();ctx.ellipse(px+19,py+19,22,18,0,0,Math.PI*2);ctx.fill();}}
// distant gate
ctx.save();ctx.translate(gate.x,gate.y);ctx.globalAlpha=relics.every(r=>r.found)?1:.35;ctx.shadowBlur=22;ctx.shadowColor='#d3d394';ctx.strokeStyle='#a9b48d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-14,12);ctx.lineTo(-14,-14);ctx.quadraticCurveTo(0,-29,14,-14);ctx.lineTo(14,12);ctx.stroke();ctx.beginPath();ctx.moveTo(-9,12);ctx.lineTo(-9,-12);ctx.quadraticCurveTo(0,-22,9,-12);ctx.lineTo(9,12);ctx.stroke();ctx.fillStyle='#c1ce8a';ctx.fillRect(-2,-3,4,4);ctx.restore();
// drops of lantern oil
for(const w of wicks)if(!w.taken){let bob=Math.sin(elapsed*2+w.phase)*3;ctx.save();ctx.translate(w.x,w.y+bob);ctx.fillStyle='#ead18a';ctx.shadowColor='#f3d880';ctx.shadowBlur=13;ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);ctx.fill();ctx.restore()}
// echoes
for(let i=0;i<relics.length;i++){let r=relics[i];if(r.found)continue;let bob=Math.sin(elapsed*1.5+r.phase)*5;ctx.save();ctx.translate(r.x,r.y+bob);ctx.rotate(Math.sin(elapsed+r.phase)*.08);ctx.fillStyle='#d5dfa1';ctx.shadowColor='#d5eb9a';ctx.shadowBlur=25;ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(8,0);ctx.lineTo(0,11);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle='#697653';ctx.beginPath();ctx.arc(0,0,2.4,0,7);ctx.fill();ctx.restore()}
for(const d of decor){if(d.x<camX-30||d.x>camX+W+30||d.y<camY-30||d.y>camY+H+30)continue;ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);ctx.scale(d.s,d.s);if(d.type==='eye'){drawTree(0,0,d.s,true)}else if(d.type==='fern'){ctx.strokeStyle='#526149';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,4);ctx.quadraticCurveTo(0,-5,9,-6);ctx.moveTo(-5,3);ctx.lineTo(-8,-3);ctx.moveTo(-1,0);ctx.lineTo(-1,-7);ctx.moveTo(4,-3);ctx.lineTo(7,-8);ctx.stroke()}else if(d.type==='mushroom'){ctx.fillStyle='#c58a6b';ctx.beginPath();ctx.ellipse(0,1,5,3,0,0,7);ctx.fill();ctx.fillStyle='#ddd0b0';ctx.fillRect(-1,1,2,5)}else if(d.type==='stone'){ctx.fillStyle='#434a3c';ctx.beginPath();ctx.ellipse(0,2,6,4,.2,0,7);ctx.fill()}else{ctx.strokeStyle='#9b9980';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-4,2);ctx.lineTo(1,-2);ctx.lineTo(5,3);ctx.stroke()}ctx.restore()}
for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(tiles[y][x]===1){const n=tileColor(x,y);if(n>.10)drawTree(x*TS+20,y*TS+26,.77+n*.36,n>.94)}
// player silhouette and carried lantern
ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.face);ctx.fillStyle='#090d0b';ctx.beginPath();ctx.ellipse(0,4,8,10,0,0,7);ctx.fill();ctx.fillStyle='#a2a48a';ctx.beginPath();ctx.arc(0,-5,5,0,7);ctx.fill();ctx.fillStyle='#d2c890';ctx.shadowColor='#e1d494';ctx.shadowBlur=lantern&&player.battery>0?13:0;ctx.beginPath();ctx.arc(5,0,2.5,0,7);ctx.fill();ctx.restore();
// The listener is almost never fully visible.
let bd=dist(beast,player),beastAlpha=Math.max(0,1-bd/290);if(beastAlpha>.02){ctx.save();ctx.globalAlpha=beastAlpha*.7;ctx.translate(beast.x,beast.y);ctx.fillStyle='#030605';ctx.beginPath();ctx.ellipse(0,0,13,22,Math.sin(elapsed)*.13,0,7);ctx.fill();ctx.fillStyle='#d0d59a';ctx.shadowColor='#d9ef9a';ctx.shadowBlur=15;ctx.fillRect(-6,-11,3,2);ctx.fillRect(4,-11,3,2);ctx.restore()}
ctx.restore();
// Darkness and lantern pool. The scene itself remains visible as a dim, uneasy memory.
let cx=W/2,cy=H/2,radius=lantern&&player.battery>0?Math.max(105,236*(.42+player.battery/175)):115;let darkness=ctx.createRadialGradient(cx,cy,Math.min(70,radius*.32),cx,cy,Math.max(W,H)*.73);darkness.addColorStop(0,lantern?'rgba(2,5,4,.08)':'rgba(2,5,4,.55)');darkness.addColorStop(Math.min(.72,radius/(Math.max(W,H)*.73)),lantern?'rgba(2,5,4,.28)':'rgba(2,5,4,.72)');darkness.addColorStop(1,'rgba(2,5,4,.96)');ctx.fillStyle=darkness;ctx.fillRect(0,0,W,H);
if(lantern&&player.battery>0){let glow=ctx.createRadialGradient(cx,cy,5,cx,cy,radius);glow.addColorStop(0,'rgba(206,211,154,.10)');glow.addColorStop(.55,'rgba(175,194,130,.045)');glow.addColorStop(1,'rgba(175,194,130,0)');ctx.fillStyle=glow;ctx.fillRect(cx-radius,cy-radius,radius*2,radius*2)}
// Threat cues, compass-esque noise at the edge.
if(dist(beast,player)<165){let strength=(165-dist(beast,player))/165;ctx.fillStyle=`rgba(117,31,26,${strength*.10})`;ctx.fillRect(0,0,W,H)}
}

function update(dt){if(mode!=='playing')return;elapsed+=dt;player.invuln=Math.max(0,player.invuln-dt);pulse=Math.max(0,pulse-dt*1.6);const left=keys.a||keys.arrowleft,right=keys.d||keys.arrowright,up=keys.w||keys.arrowup,down=keys.s||keys.arrowdown;let vx=(right?1:0)-(left?1:0),vy=(down?1:0)-(up?1:0),moving=!!(vx||vy);if(moving){let m=Math.hypot(vx,vy);vx/=m;vy/=m;player.face=Math.atan2(vy,vx);player.walk+=dt*(touchRun||keys.shift?12:7)}let sprint=moving&&(touchRun||keys.shift)&&player.stamina>1;let speed=sprint?145:83;if(sprint)player.stamina=Math.max(0,player.stamina-dt*23);else player.stamina=Math.min(100,player.stamina+dt*(moving?8:16));moveBody(player,vx*speed*dt,vy*speed*dt,player.r);
if(lantern&&player.battery>0)player.battery=Math.max(0,player.battery-dt*(sprint?.39:.24));if(player.battery===0&&lantern){lantern=false;showToast('THE LANTERN WENT OUT')}
// Noise is a real choice: running is faster but the listener can hear it.
let noise=sprint?1:.13;beast.alert=Math.max(beast.alert*.995,Math.max(0,1-dist(beast,player)/(sprint?920:340))*noise);let bd=dist(beast,player);let hunting=bd<480||beast.alert>.12;if(hunting){beast.tx=player.x;beast.ty=player.y;beast.wander=0}else{beast.wander-=dt;if(beast.wander<=0){beast.wander=rand(1,3);beast.tx=beast.x+rand(-220,220);beast.ty=beast.y+rand(-220,220)}}
let dx=beast.tx-beast.x,dy=beast.ty-beast.y,len=Math.hypot(dx,dy)||1;let bs=(hunting?48:26)+(beast.alert*27);if(lantern&&player.battery>0&&bd<190)bs*=.62;let mx=dx/len*bs*dt,my=dy/len*bs*dt;let ox=beast.x,oy=beast.y;moveBody(beast,mx,my,9);if(Math.abs(beast.x-ox)+Math.abs(beast.y-oy)<.01&&hunting){let alt=[[-my,mx],[my,-mx],[mx*.7-my*.7,my*.7+mx*.7],[mx*.7+my*.7,my*.7-mx*.7]];let v=pick(alt);moveBody(beast,v[0],v[1],9)}
if(bd<30){if(lantern&&player.battery>2){beast.alert=Math.max(0,beast.alert-.1);player.battery=Math.max(0,player.battery-dt*8);if(Math.random()<dt*1.8)showToast('IT HATES THE LIGHT')}else if(player.invuln<=0){player.health-=30;player.invuln=1.35;shake=11;beast.alert=1;player.stamina=Math.max(0,player.stamina-25);if(player.health<=0){endGame(false);return}showToast('IT FOUND YOU — KEEP MOVING')}}
for(const r of relics)if(!r.found&&Math.hypot(r.x-player.x,r.y-player.y)<23){r.found=true;player.battery=Math.min(100,player.battery+8);showToast('ECHO RECOVERED  ·  '+relics.filter(x=>x.found).length+' / 3');if(relics.every(x=>x.found)){ui.goal.textContent='Reach the old gate';showToast('THE GATE IS WAITING') }}
for(const w of wicks)if(!w.taken&&Math.hypot(w.x-player.x,w.y-player.y)<21){w.taken=true;player.wicks++;player.battery=Math.min(100,player.battery+27);showToast('LANTERN WICK  +27');}
if(relics.every(r=>r.found)&&Math.hypot(gate.x-player.x,gate.y-player.y)<27){endGame(true);return}
if(elapsed>0&&Math.floor(elapsed/90)+1>night){night=Math.floor(elapsed/90)+1;ui.night.textContent=['I','II','III','IV','V'][Math.min(4,night-1)];showToast('THE NIGHT GROWS LONGER')}
// Screen feedback and all live HUD values.
ui.breath.style.width=player.stamina+'%';ui.breath.style.background=player.stamina<25?'#c47d5d':'#c4d27b';ui.breathNum.textContent=Math.round(player.stamina);ui.battery.style.width=player.battery+'%';ui.batteryNum.textContent=Math.round(player.battery);ui.wicks.textContent=player.wicks;ui.clock.textContent=formatTime(elapsed);ui.mood.textContent=bd<180?'VERY CLOSE':beast.alert>.35?'FOLLOWING':'LISTENING';ui.mood.style.color=bd<180?'#d18b70':'#c4d27b';document.querySelectorAll('.relic').forEach((el,i)=>el.classList.toggle('found',relics[i]?.found));}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);if(tiles.length&&player.x!==undefined){if(shake>0){ctx.save();ctx.translate(rand(-shake,shake),rand(-shake,shake));shake=Math.max(0,shake-.65);drawWorld();ctx.restore()}else drawWorld()}else{ctx.fillStyle='#0a100c';ctx.fillRect(0,0,W,H);for(let i=0;i<80;i++){let x=(i*173+elapsed*3)%W,y=(i*97)%H;ctx.fillStyle='rgba(103,125,83,.14)';ctx.fillRect(x,y,2,2)}}}
function loop(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;if(mode==='playing')update(dt);else if(mode==='menu'){elapsed+=dt*.15}render();requestAnimationFrame(loop)}
generate();requestAnimationFrame(loop);
})();
</script>
</body>
</html>

